yandex_public_patch="\n# V20.7.17: father-facing music links must stay inside Yandex Disk.\nimport os,re,json,time,threading,urllib.parse,urllib.error\n\n_YDX_LINK_FILE='/memos-data/porfirchik-last-yandex-music-links.json'\n_YDX_LOCK=threading.RLock()\n_YDX_REPAIRING=set()\n_YDX_RUNTIME_URLS={}\n_YDX_URL_RE=re.compile(r'https?://(?:yadi\\.sk|disk\\.yandex\\.[A-Za-z.]+)/[^\\s<>\\]\\)]+',re.I)\n\ndef _ydx_public_url_ok(url):\n    try:\n        u=urllib.parse.urlsplit(str(url or '').strip())\n        host=(u.hostname or '').lower()\n        if u.scheme!='https':\n            return False\n        if not (host=='yadi.sk' or host.startswith('disk.yandex.')):\n            return False\n        if not (u.path.startswith('/d/') or u.path.startswith('/i/') or u.path.startswith('/client/disk/')):\n            return False\n        return True\n    except Exception:\n        return False\n\ndef _ydx_read_index():\n    try:\n        with _YDX_LOCK:\n            with open(_YDX_LINK_FILE,'r',encoding='utf-8') as f:\n                d=json.load(f)\n        return d if isinstance(d,dict) else {}\n    except Exception:\n        return {}\n\ndef _ydx_save_index(uid,path,url):\n    if not path.startswith('disk:/Porfirchik Music/') or not _ydx_public_url_ok(url):\n        return\n    try:\n        with _YDX_LOCK:\n            d=_ydx_read_index()\n            d[str(uid)]={'path':path,'url':url,'at':int(time.time())}\n            if len(d)>40:\n                d=dict(sorted(d.items(),key=lambda kv:kv[1].get('at',0),reverse=True)[:40])\n            os.makedirs('/memos-data',exist_ok=True)\n            tmp=_YDX_LINK_FILE+'.tmp'\n            with open(tmp,'w',encoding='utf-8') as f:\n                json.dump(d,f,ensure_ascii=False)\n            os.replace(tmp,_YDX_LINK_FILE)\n    except Exception as err:\n        print('YANDEX_PUBLIC_INDEX_ERROR',type(err).__name__,flush=True)\n\ndef _ydx_stat(path):\n    return _music_yandex_api('/resources',{\n        'path':path,\n        'fields':'name,size,mime_type,public_url'\n    },'GET')\n\ndef _ydx_publish(path):\n    if not str(path).startswith('disk:/Porfirchik Music/'):\n        raise RuntimeError('invalid_music_disk_path')\n    st=_ydx_stat(path)\n    size=int(st.get('size') or 0)\n    if size<44 or size>35000000:\n        raise RuntimeError('invalid_music_file_size')\n    url=str(st.get('public_url') or '').strip()\n    if not _ydx_public_url_ok(url):\n        try:\n            _music_yandex_api('/resources/publish',{'path':path},'PUT')\n        except urllib.error.HTTPError as err:\n            # A previously published resource may return a conflict in some API states.\n            if int(getattr(err,'code',0) or 0) not in (409,423):\n                raise\n        st=_ydx_stat(path)\n        url=str(st.get('public_url') or '').strip()\n    if not _ydx_public_url_ok(url):\n        raise RuntimeError('yandex_public_url_missing')\n    _YDX_RUNTIME_URLS[url]=path\n    return {'path':path,'url':url,'size':int(st.get('size') or size)}\n\n# Existing music worker calls this after persisting a WAV.\ndef _music_signed_link(path):\n    return _ydx_publish(path)['url']\n\n_v20716_send=send\ndef send(peer,text):\n    msg=str(text or '')\n    urls=[m.group(0).rstrip('.,;') for m in _YDX_URL_RE.finditer(msg)]\n    has_old_gateway='/porfirchik/music/' in msg\n    if has_old_gateway:\n        idx=_ydx_read_index().get(str(peer),{})\n        url=str(idx.get('url') or '')\n        if _ydx_public_url_ok(url):\n            msg=('Ссылка на музыку теперь только через Яндекс.Диск: '+url)\n        else:\n            msg=('Ссылки через внешний шлюз больше не отправляю. '\n                 'Напиши «повтори ссылку на музыку» — проверю файл на Яндекс.Диске.')\n        print('MUSIC_GATEWAY_LINK_SUPPRESSED_FOR_FATHER',flush=True)\n        return _base_music_send(peer,msg)\n    if urls:\n        approved=[]\n        for url in urls:\n            path=_YDX_RUNTIME_URLS.get(url)\n            if path:\n                approved.append((url,path))\n        if len(approved)!=len(urls):\n            idx=_ydx_read_index().get(str(peer),{})\n            known_url=str(idx.get('url') or '')\n            if _ydx_public_url_ok(known_url):\n                msg=('Проверенная ссылка на Яндекс.Диск: '+known_url)\n            else:\n                msg=('Не могу подтвердить эту ссылку Яндекс.Диска. '\n                     'Непроверенный адрес отправлять не буду.')\n            print('MUSIC_UNVERIFIED_YANDEX_LINK_BLOCKED',flush=True)\n            return _base_music_send(peer,msg)\n        out=_base_music_send(peer,msg)\n        # Associate the verified just-published URL with the peer.\n        _ydx_save_index(peer,approved[0][1],approved[0][0])\n        return out\n    return _v20716_send(peer,msg)\n\ndef _ydx_candidate_paths(uid,request_text):\n    out=[]\n    idx=_ydx_read_index().get(str(uid),{})\n    p=str(idx.get('path') or '')\n    if p.startswith('disk:/Porfirchik Music/'):\n        out.append(p)\n    # Genuine old gateway links contain the Disk path and remain useful for migration.\n    for rec in _music_valid_urls(request_text):\n        out.append(rec['path'])\n    try:\n        history=_music_vk_api('messages.getHistory',{'peer_id':int(uid),'count':100}) or {}\n        for item in history.get('items') or []:\n            if not item.get('out'):\n                continue\n            for rec in _music_valid_urls(item.get('text','')):\n                out.append(rec['path'])\n    except Exception as err:\n        print('YANDEX_PUBLIC_HISTORY_ERROR',type(err).__name__,flush=True)\n    seen=set()\n    return [x for x in out if x not in seen and not seen.add(x)]\n\ndef _music_link_repair_worker(uid,request_text):\n    try:\n        for path in _ydx_candidate_paths(uid,request_text)[:6]:\n            try:\n                rec=_ydx_publish(path)\n                _ydx_save_index(uid,rec['path'],rec['url'])\n                _base_music_send(uid,'Проверенная ссылка прямо на Яндекс.Диск: '+rec['url'])\n                state['music_link_repair_last_ok']=True\n                state['music_delivery']='yandex-public-url'\n                print('YANDEX_PUBLIC_REISSUE_OK',json.dumps({'bytes':rec['size']},ensure_ascii=False),flush=True)\n                return\n            except Exception as err:\n                print('YANDEX_PUBLIC_REISSUE_SKIP',type(err).__name__,flush=True)\n        state['music_link_repair_last_ok']=False\n        _base_music_send(uid,\n            'Не нашёл доступного сохранённого WAV на Яндекс.Диске. '\n            'Непроверенную ссылку присылать не буду.')\n    finally:\n        with _MUSIC_LINK_LOCK:\n            _MUSIC_LINK_REPAIRING.discard(str(uid))\n        with _YDX_LOCK:\n            _YDX_REPAIRING.discard(str(uid))\n\n# One-time qualification of an existing real WAV, persisted so Railway wake-ups do not republish repeatedly.\ndef _ydx_startup_probe():\n    marker='/memos-data/porfirchik-yandex-public-v20717.json'\n    if os.path.exists(marker):\n        return\n    path='disk:/Porfirchik Music/porfirchik-20261001-143205-7a69b5bf.wav'\n    try:\n        rec=_ydx_publish(path)\n        with open(marker+'.tmp','w',encoding='utf-8') as f:\n            json.dump({'path':path,'url':rec['url'],'size':rec['size']},f,ensure_ascii=False)\n        os.replace(marker+'.tmp',marker)\n        print('ND_V20_7_17_YANDEX_PUBLIC_PROBE_OK',\n              json.dumps({'url':rec['url'],'bytes':rec['size']},ensure_ascii=False),flush=True)\n    except Exception as err:\n        print('ND_V20_7_17_YANDEX_PUBLIC_PROBE_FAILED',type(err).__name__,flush=True)\n\nthreading.Thread(target=_ydx_startup_probe,daemon=True).start()\nstate['music_links_policy']='yandex-public-url-only'\nstate['music_delivery']='yandex-public-url'\nprint('ND_V20_7_17_YANDEX_PUBLIC_LINKS_READY',flush=True)\n"
